						Stk[Inst[2]] = Wrap(NewProto, NewUvals, Env);
					elseif (Enum > 98) then
						Stk[Inst[2]] = Stk[Inst[3]] * Stk[Inst[4]];
					elseif (Stk[Inst[2]] < Inst[4]) then
						VIP = VIP + 1;
					else
						VIP = Inst[3];
					end
				elseif (Enum <= 101) then
					if (Enum == 100) then
						Stk[Inst[2]] = Stk[Inst[3]][Inst[4]];
					else
						Stk[Inst[2]][Inst[3]] = Inst[4];
					end
				elseif (Enum > 102) then
					local B = Stk[Inst[4]];
					if not B then
